INSERT INTO `v1_e2ebb310c7f902cfa515d7910d3e1150f1b469fac2fd186ec39e67bb2b4c87d0` VALUES ("チームでクイズに挑みましょう！\nソロで自分の実力を試すか、マル\nチで仲間と一緒に遊ぶか、好きな\nモードを選んでくださいね♪", "2022-02-15 15:00:00", 1010, 4, 1010001, "2030-04-01 14:00:00", 0, 190801);
